static void DukeScreenMessage(const FString& Text, const FColor& Color, float Seconds = 5.f)
{
	if (GEngine) GEngine->AddOnScreenDebugMessage(-1, Seconds, Color, Text);
	UE_LOG(LogTemp, Log, TEXT("[Galaxy] %s"), *Text);
}

FString FDukeTatooineNames::NewSettlementName(int32 Index)
{
	static const TCHAR* Prefixes[] = { TEXT("Anchorhead"), TEXT("Mos Eisley"), TEXT("Mos Espa"), TEXT("Motesta"), TEXT("Wayfar"), TEXT("Aruba"), TEXT("Bestine") };
	static const TCHAR* Suffixes[] = { TEXT("Outpost"), TEXT("Wastes Settlement"), TEXT("Ridge"), TEXT("Oasis"), TEXT("Dune Annex"), TEXT("Station") };
	const int32 I = FMath::Abs(Index);
	return FString::Printf(TEXT("%s-%s %d"), Prefixes[I % UE_ARRAY_COUNT(Prefixes)], Suffixes[(I + 2) % UE_ARRAY_COUNT(Suffixes)], I + 1);
}

