ADukeWeaponBase::ADukeWeaponBase()
{
	PrimaryActorTick.bCanEverTick = false;
	WeaponMesh = CreateDefaultSubobject<USkeletalMeshComponent>(TEXT("WeaponMesh"));
	RootComponent = WeaponMesh;
	WeaponMesh->SetSimulatePhysics(false);
	WeaponMesh->SetCollisionProfileName(TEXT("NoCollision"));
	PickupSphere = CreateDefaultSubobject<USphereComponent>(TEXT("PickupSphere"));
	PickupSphere->SetupAttachment(RootComponent);
	PickupSphere->SetSphereRadius(150.f);
	PickupSphere->SetCollisionProfileName(TEXT("Trigger"));
}
void ADukeWeaponBase::EquipToHand(ACharacter* Character)
{
	if (!Character) return;
	WeaponMesh->SetSimulatePhysics(false);
	WeaponMesh->SetCollisionProfileName(TEXT("NoCollision"));
	AttachToComponent(Character->GetMesh(), FAttachmentTransformRules(EAttachmentRule::SnapToTarget, EAttachmentRule::SnapToTarget, EAttachmentRule::KeepWorld, true), HandSocketName);
}
void ADukeWeaponBase::HolsterToBelt(ACharacter* Character)
{
	if (!Character) return;
	WeaponMesh->SetSimulatePhysics(false);
	AttachToComponent(Character->GetMesh(), FAttachmentTransformRules(EAttachmentRule::SnapToTarget, EAttachmentRule::SnapToTarget, EAttachmentRule::KeepWorld, true), BeltSocketName);
}
void ADukeWeaponBase::DropWeapon()
{
	DetachFromActor(FDetachmentTransformRules(EDetachmentRule::KeepWorld, true));
	SetOwner(nullptr);
	WeaponMesh->SetCollisionProfileName(TEXT("PhysicsActor"));
	WeaponMesh->SetSimulatePhysics(true);
	WeaponMesh->WakeAllRigidBodies();
}

ADukeLightsaberWeapon::ADukeLightsaberWeapon()
{
	PrimaryActorTick.bCanEverTick = true;
	WeaponType = EDukeWeaponType::Lightsaber;
	HandSocketName = TEXT("Socket_Saber_Hand");
	BeltSocketName = TEXT("Socket_Saber_Belt");
}
void ADukeLightsaberWeapon::BeginPlay()
{
	Super::BeginPlay();
	LastBase = WeaponMesh->GetSocketLocation(BladeBaseSocket);
	LastTip = WeaponMesh->GetSocketLocation(BladeTipSocket);
}
void ADukeLightsaberWeapon::Tick(float DeltaTime)
{
	Super::Tick(DeltaTime);
	CurrentBladeLength = FMath::FInterpTo(CurrentBladeLength, bIsBladeActive ? MaxBladeLength : 0.f, DeltaTime, 12.f);
	WeaponMesh->SetScalarParameterValueOnMaterials(TEXT("BladeLength"), CurrentBladeLength);
	if (CurrentBladeLength > 0.05f && bPhysicsDetectionAllowed) SweepBlade();
	else HitThisSwing.Reset();
	LastBase = WeaponMesh->GetSocketLocation(BladeBaseSocket);
	LastTip = WeaponMesh->GetSocketLocation(BladeTipSocket);
}
// The blade sweeps a sheet between last frame's and this frame's edge (base -> tip): fast swings cannot skip a target.
void ADukeLightsaberWeapon::SweepBlade()
{
	const FVector Base = WeaponMesh->GetSocketLocation(BladeBaseSocket);
	const FVector Tip = WeaponMesh->GetSocketLocation(BladeTipSocket);
	FCollisionQueryParams Q(SCENE_QUERY_STAT(DukeSaberSweep), false, this);
	Q.AddIgnoredActor(GetOwner());
	TArray<FHitResult> Hits;
	for (int32 i = 0; i <= 4; ++i)   // five points along the edge
	{
		const float A = i / 4.f;
		const FVector From = FMath::Lerp(LastBase, LastTip, A * CurrentBladeLength / FMath::Max(MaxBladeLength, 0.01f));
		const FVector To = FMath::Lerp(Base, Tip, A * CurrentBladeLength / FMath::Max(MaxBladeLength, 0.01f));
		TArray<FHitResult> H;
		GetWorld()->SweepMultiByChannel(H, From, To, FQuat::Identity, ECC_WorldDynamic, FCollisionShape::MakeSphere(6.f), Q);
		Hits.Append(H);
	}
	for (const FHitResult& Hit : Hits)
	{
		AActor* A = Hit.GetActor();
		if (!A) continue;
		if (ADukeBlasterBolt* Bolt = Cast<ADukeBlasterBolt>(A))
		{
			// deflect: reflect the bolt off the blade and speed it up
			if (Bolt->Movement) { const FVector V = FVector::Reflect(Bolt->Movement->Velocity.GetSafeNormal(), Hit.ImpactNormal) * Bolt->Movement->Velocity.Size() * 1.5f; Bolt->Movement->Velocity = V; Bolt->SetActorRotation(V.Rotation()); }
			continue;
		}
		if (UPrimitiveComponent* C = Hit.GetComponent())
			if (C->IsSimulatingPhysics()) C->AddImpulseAtLocation((Hit.ImpactPoint - GetActorLocation()).GetSafeNormal() * 2000.f, Hit.ImpactPoint);
		if (!HitThisSwing.Contains(A) && Cast<APawn>(A))
		{
			HitThisSwing.Add(A);
			FPointDamageEvent E(SaberDamage, Hit, (Tip - LastTip).GetSafeNormal(), UDukeSaberDamageType::StaticClass());
			A->TakeDamage(SaberDamage, E, GetInstigatorController(), this);
		}
	}
}

ADukeBlasterRifleWeapon::ADukeBlasterRifleWeapon()
{
	WeaponType = EDukeWeaponType::BlasterRifle;
	HandSocketName = TEXT("Socket_Blaster_Hand");
	BeltSocketName = TEXT("Socket_Blaster_Belt");
}
// Crosshair aim (Outlaws-style): trace from the camera, the bolt flies from the muzzle to what the crosshair is on.
void ADukeBlasterRifleWeapon::FireBlaster(ACharacter* Shooter)
{
	if (!Shooter || !Shooter->GetController()) return;
	FVector Eye; FRotator Look;
	Shooter->GetController()->GetPlayerViewPoint(Eye, Look);
	const FVector End = Eye + Look.Vector() * MaxRange;
	FCollisionQueryParams Q(SCENE_QUERY_STAT(DukeBlasterAim), false, this); Q.AddIgnoredActor(Shooter);
	FHitResult Hit;
	const FVector Aim = GetWorld()->LineTraceSingleByChannel(Hit, Eye, End, ECC_Visibility, Q) ? Hit.ImpactPoint : End;
	const FVector Muzzle = WeaponMesh->DoesSocketExist(MuzzleSocketName) ? WeaponMesh->GetSocketLocation(MuzzleSocketName) : GetActorLocation();
	ADukeBlasterBolt::Fire(GetWorld(), Shooter, Muzzle, (Aim - Muzzle).GetSafeNormal(), BaseDamage, 9000.f, BoltColor);
}

void UAnimNotifyState_DukeSaberPhysics::SetAllowed(USkeletalMeshComponent* MeshComp, bool bAllowed)
{
	if (!MeshComp || !MeshComp->GetOwner()) return;
	TArray<AActor*> Attached; MeshComp->GetOwner()->GetAttachedActors(Attached);
	for (AActor* A : Attached) if (ADukeLightsaberWeapon* S = Cast<ADukeLightsaberWeapon>(A)) S->bPhysicsDetectionAllowed = bAllowed;
}
void UAnimNotifyState_DukeSaberPhysics::NotifyBegin(USkeletalMeshComponent* MeshComp, UAnimSequenceBase* Animation, float TotalDuration, const FAnimNotifyEventReference& EventReference) { SetAllowed(MeshComp, true); }
void UAnimNotifyState_DukeSaberPhysics::NotifyEnd(USkeletalMeshComponent* MeshComp, UAnimSequenceBase* Animation, const FAnimNotifyEventReference& EventReference) { SetAllowed(MeshComp, false); }

