ADukeTerritoryZone::ADukeTerritoryZone()
{
	PrimaryActorTick.bCanEverTick = false;
	ZoneBounds = CreateDefaultSubobject<USphereComponent>(TEXT("ZoneBounds"));
	RootComponent = ZoneBounds;
	ZoneBounds->SetSphereRadius(7500.f);
	ZoneBounds->SetCollisionProfileName(TEXT("NoCollision"));
}
void ADukeTerritoryZone::BeginPlay()
{
	Super::BeginPlay();
	if (UDukeGalaxyDirector* D = GetWorld()->GetSubsystem<UDukeGalaxyDirector>()) D->Territories.AddUnique(this);
}
void ADukeTerritoryZone::ProcessEnemyCasualty(float Weight)
{
	if (ZoneStatus == EDukeTerritoryStatus::Liberated) return;
	OccupyingForceStrength = FMath::Clamp(OccupyingForceStrength - Weight, 0.f, 100.f);
	if (OccupyingForceStrength <= 0.f) { ZoneStatus = EDukeTerritoryStatus::Liberated; DukeScreenMessage(FString::Printf(TEXT("%s has been LIBERATED!"), *ZoneName), FColor::Green); }
}
ADukeTerritoryZone* ADukeTerritoryZone::ZoneAt(const UWorld* World, const FVector& L)
{
	if (!World) return nullptr;
	for (TActorIterator<ADukeTerritoryZone> It(const_cast<UWorld*>(World)); It; ++It)
		if (FVector::Dist(It->GetActorLocation(), L) <= It->ZoneBounds->GetScaledSphereRadius()) return *It;
	return nullptr;
}

// ---------------- smart NPCs ----------------
ADukeSmartNPC::ADukeSmartNPC() { PrimaryActorTick.bCanEverTick = true; }
void ADukeSmartNPC::BeginPlay()
{
	Super::BeginPlay();
	LootableEarrings = { TEXT("Kyber-Flake Stud"), TEXT("Krayt-Bone Hoop") };
	if (!AssignedZone) AssignedZone = ADukeTerritoryZone::ZoneAt(GetWorld(), GetActorLocation());
	if (UDukeGalaxyDirector* D = GetWorld()->GetSubsystem<UDukeGalaxyDirector>()) D->Register(this);
	Hour = FMath::RandRange(0, 23);
}
void ADukeSmartNPC::EndPlay(const EEndPlayReason::Type Reason)
{
	if (UWorld* W = GetWorld()) if (UDukeGalaxyDirector* D = W->GetSubsystem<UDukeGalaxyDirector>()) D->Unregister(this);
	Super::EndPlay(Reason);
}
// Daily schedule: one step per in-game hour (sleep 0-6, eat, work 8-16, errands, chores, eat, sleep).
void ADukeSmartNPC::Tick(float DeltaTime)
{
	Super::Tick(DeltaTime);
	if (CurrentState == EDukeNpcState::CombatDuty || CurrentState == EDukeNpcState::EnslavedInSaltMines ||
		CurrentState == EDukeNpcState::InterrogatedAtCheckpoint || CurrentState == EDukeNpcState::Dead || CurrentState == EDukeNpcState::SeekingRevenge) return;
	ScheduleTimer += DeltaTime;
	if (ScheduleTimer < ScheduleStepSeconds) return;
	ScheduleTimer = 0.f; Hour = (Hour + 1) % 24;
	if (Hour < 6) CurrentState = EDukeNpcState::Sleeping;
	else if (Hour < 8 || (Hour >= 18 && Hour < 19)) CurrentState = EDukeNpcState::Eating;
	else if (Hour < 16) CurrentState = EDukeNpcState::Working;
	else if (Hour < 18) CurrentState = EDukeNpcState::RunningErrands;
	else CurrentState = EDukeNpcState::Chores;
}
float ADukeSmartNPC::TakeDamage(float DamageAmount, FDamageEvent const& DamageEvent, AController* EventInstigator, AActor* DamageCauser)
{
	const float D = Super::TakeDamage(DamageAmount, DamageEvent, EventInstigator, DamageCauser);
	if (CurrentState == EDukeNpcState::Dead || D <= 0.f) return D;
	Health -= D;
	AActor* Killer = EventInstigator && EventInstigator->GetPawn() ? EventInstigator->GetPawn() : DamageCauser;
	if (Health <= 0.f) Die(Killer);
	return D;
}
void ADukeSmartNPC::Die(AActor* Killer)
{
	CurrentState = EDukeNpcState::Dead;
	if (bIsEnemyFaction && AssignedZone) AssignedZone->ProcessEnemyCasualty(8.f);
	// the family takes it personally: spouse, children and cousins turn into a revenge clan
	TArray<ADukeSmartNPC*> Kin;
	if (Family.Spouse) Kin.Add(Family.Spouse);
	for (ADukeSmartNPC* C : Family.Children) if (C) Kin.Add(C);
	for (ADukeSmartNPC* C : Family.Cousins) if (C) Kin.Add(C);
	for (ADukeSmartNPC* K : Kin) K->NotifyFamilyMurdered(this, Killer);
	GetMesh()->SetSimulatePhysics(true);   // limp
	SetLifeSpan(120.f);
}
void ADukeSmartNPC::NotifyFamilyMurdered(ADukeSmartNPC* SlainRelative, AActor* Killer)
{
	if (CurrentState == EDukeNpcState::Dead || CurrentState == EDukeNpcState::SeekingRevenge || !Killer) return;
	CurrentState = EDukeNpcState::SeekingRevenge; TargetPlayerRef = Killer;
	Family.ActiveClanName = FString::Printf(TEXT("The Blood Vengeance of %s"), *Family.FamilyLastName);
	for (ADukeSmartNPC* Cousin : Family.Cousins) if (Cousin) Cousin->NotifyFamilyMurdered(SlainRelative, Killer);
}
TArray<FString> ADukeSmartNPC::LootAndStripEarrings() { TArray<FString> Out = LootableEarrings; LootableEarrings.Empty(); return Out; }

// ---------------- occupation ----------------
ADukeOccupationStructure::ADukeOccupationStructure()
{
	PrimaryActorTick.bCanEverTick = false;
	BaseMesh = CreateDefaultSubobject<UStaticMeshComponent>(TEXT("BaseMesh"));
	RootComponent = BaseMesh;
	ProximityTrigger = CreateDefaultSubobject<USphereComponent>(TEXT("ProximityTrigger"));
	ProximityTrigger->SetupAttachment(RootComponent);
	ProximityTrigger->SetSphereRadius(2000.f);
	ProximityTrigger->SetCollisionProfileName(TEXT("Trigger"));
	GarrisonClass = ADukeTrooper::StaticClass();
}
void ADukeOccupationStructure::BeginPlay()
{
	Super::BeginPlay();
	if (!OverlappingTerritoryZone) OverlappingTerritoryZone = ADukeTerritoryZone::ZoneAt(GetWorld(), GetActorLocation());
	ProximityTrigger->OnComponentBeginOverlap.AddDynamic(this, &ADukeOccupationStructure::OnPerimeterBreached);
}
void ADukeOccupationStructure::OnPerimeterBreached(UPrimitiveComponent*, AActor* OtherActor, UPrimitiveComponent*, int32, bool, const FHitResult&)
{
	if (bIsCaptured || bGarrisonSpawned || !OverlappingTerritoryZone || !OtherActor) return;
	const APawn* Pawn = Cast<APawn>(OtherActor);
	if (!Pawn || !Pawn->IsPlayerControlled()) return;    // the player (and only the player) trips the alarm
	OverlappingTerritoryZone->ZoneStatus = EDukeTerritoryStatus::Contested;
	DukeScreenMessage(FString::Printf(TEXT("PERIMETER BREACHED: attacking the Imperial %s in %s!"), Tier == EDukeBaseTier::TerritoryMegaBase ? TEXT("MEGA-BASE") : TEXT("OUTPOST"), *OverlappingTerritoryZone->ZoneName), FColor::Red, 6.f);
	SpawnGarrison();
}
void ADukeOccupationStructure::SpawnGarrison()
{
	bGarrisonSpawned = true;
	const int32 N = Tier == EDukeBaseTier::TerritoryMegaBase ? 12 : 5;
	FActorSpawnParameters P; P.SpawnCollisionHandlingOverride = ESpawnActorCollisionHandlingMethod::AdjustIfPossibleButAlwaysSpawn;
	for (int32 i = 0; i < N; ++i)
	{
		const FVector L = GetActorLocation() + FVector(FMath::RandRange(-400.f, 400.f), FMath::RandRange(-400.f, 400.f), 100.f);
		if (ADukeTrooper* T = GetWorld()->SpawnActor<ADukeTrooper>(GarrisonClass ? *GarrisonClass : ADukeTrooper::StaticClass(), L, FRotator(0, FMath::RandRange(0.f, 360.f), 0), P))
			T->Faction = EDukeFaction::Empire;
	}
}

ADukeDestructibleStructure::ADukeDestructibleStructure()
{
	PrimaryActorTick.bCanEverTick = true;
	BuildingMesh = CreateDefaultSubobject<UStaticMeshComponent>(TEXT("BuildingMesh"));
	RootComponent = BuildingMesh;
}
void ADukeDestructibleStructure::ProcessStructuralDamage()
{
	if (Condition == EDukeStructureCondition::Destroyed) return;
	IntactTransform = GetActorTransform();
	Condition = EDukeStructureCondition::Destroyed;
	BuildingMesh->SetCollisionProfileName(TEXT("PhysicsActor"));
	BuildingMesh->SetSimulatePhysics(true);
}
void ADukeDestructibleStructure::BeginRebuild() { if (Condition == EDukeStructureCondition::Destroyed) { Condition = EDukeStructureCondition::Rebuilding; RebuildProgress = 0.f; } }
void ADukeDestructibleStructure::Tick(float DeltaTime)
{
	Super::Tick(DeltaTime);
	if (Condition != EDukeStructureCondition::Rebuilding) return;
	RebuildProgress += DeltaTime / FMath::Max(RebuildSeconds, 1.f);
	if (RebuildProgress >= 1.f)
	{
		BuildingMesh->SetSimulatePhysics(false);
		SetActorTransform(IntactTransform);
		BuildingMesh->SetCollisionProfileName(TEXT("BlockAll"));
		Condition = EDukeStructureCondition::Intact; RebuildProgress = 0.f;
	}
}

// ---------------- galaxy director ----------------
void UDukeGalaxyDirector::OnWorldBeginPlay(UWorld& InWorld)
{
	Super::OnWorldBeginPlay(InWorld);
	for (TActorIterator<ADukeDestructibleStructure> It(&InWorld); It; ++It) TownStructures.AddUnique(*It);
}
void UDukeGalaxyDirector::Tick(float DeltaTime)
{
	if (bAllOutWar) return;
	SweepTimer += DeltaTime;
	if (SweepTimer < 30.f) return;
	SweepTimer = 0.f;
	RunOppressionSweep();
	EvaluateWar();
}
// Occupied zones: checkpoint stops for people out on errands, night raids that send sleepers to the salt mines.
void UDukeGalaxyDirector::RunOppressionSweep()
{
	for (ADukeSmartNPC* N : NPCs)
	{
		if (!N || N->CurrentState == EDukeNpcState::Dead || N->bIsEnemyFaction || N->bIsRecruited) continue;
		if (!N->AssignedZone || N->AssignedZone->ZoneStatus != EDukeTerritoryStatus::Occupied) continue;
		const int32 R = FMath::RandRange(1, 100);
		if (R <= 10 && N->CurrentState == EDukeNpcState::RunningErrands) { N->CurrentState = EDukeNpcState::InterrogatedAtCheckpoint; DukeScreenMessage(TEXT("Imperial checkpoint: a traveller is stopped for inspection."), FColor::Yellow, 4.f); }
		else if (R > 10 && R <= 15 && N->CurrentState == EDukeNpcState::Sleeping) { N->CurrentState = EDukeNpcState::EnslavedInSaltMines; DukeScreenMessage(TEXT("Imperial raid: homes broken into, civilians marched to the salt flats."), FColor::Red); }
	}
}
void UDukeGalaxyDirector::EvaluateWar()
{
	if (Territories.Num() == 0) return;
	for (ADukeTerritoryZone* Z : Territories) if (Z && Z->ZoneStatus != EDukeTerritoryStatus::Liberated) return;
	TriggerAllOutWar();
}
// Every zone liberated: the Empire commits everything it has left.
void UDukeGalaxyDirector::TriggerAllOutWar()
{
	bAllOutWar = true;
	DukeScreenMessage(TEXT("THE EMPIRE COMMITS ITS REAR-GUARD ARMADA: ALL-OUT WAR!"), FColor::Red, 15.f);
	UWorld* W = GetWorld(); if (!W) return;
	FActorSpawnParameters P; P.SpawnCollisionHandlingOverride = ESpawnActorCollisionHandlingMethod::AdjustIfPossibleButAlwaysSpawn;
	for (ADukeTerritoryZone* Z : Territories)
	{
		if (!Z) continue;
		Z->ZoneStatus = EDukeTerritoryStatus::Contested;
		for (int32 i = 0; i < 6; ++i)
			if (ADukeTrooper* T = W->SpawnActor<ADukeTrooper>(ADukeTrooper::StaticClass(), Z->GetActorLocation() + FVector(FMath::RandRange(-600.f, 600.f), FMath::RandRange(-600.f, 600.f), 100.f), FRotator::ZeroRotator, P))
				T->Faction = EDukeFaction::Empire;
	}
}
void UDukeGalaxyDirector::GenerateSettlement(FVector Location)
{
	UWorld* W = GetWorld(); if (!W) return;
	const FString Name = FDukeTatooineNames::NewSettlementName(SettlementCounter++);
	if (ADukeDestructibleStructure* Hub = W->SpawnActor<ADukeDestructibleStructure>(ADukeDestructibleStructure::StaticClass(), Location, FRotator::ZeroRotator))
	{
		Hub->Tags.Add(FName(*Name));   // settlement name (actor labels exist only in the editor)
		TownStructures.Add(Hub);
		UE_LOG(LogTemp, Log, TEXT("[Galaxy] A new settlement rises in the wastes of Tatooine: %s"), *Name);
	}
}

// ---------------- player Jedi ----------------
ADukeJediPlayer::ADukeJediPlayer() { PrimaryActorTick.bCanEverTick = true; SaberClass = ADukeLightsaberWeapon::StaticClass(); }
void ADukeJediPlayer::BeginPlay()
{
	Super::BeginPlay();
	if (APlayerController* PC = Cast<APlayerController>(Controller))
		if (UEnhancedInputLocalPlayerSubsystem* Sub = ULocalPlayer::GetSubsystem<UEnhancedInputLocalPlayerSubsystem>(PC->GetLocalPlayer()))
			if (CombatMappingContext) Sub->AddMappingContext(CombatMappingContext, 0);
	FActorSpawnParameters P; P.Owner = this; P.Instigator = this;
	if (ADukeLightsaberWeapon* Saber = GetWorld()->SpawnActor<ADukeLightsaberWeapon>(SaberClass ? *SaberClass : ADukeLightsaberWeapon::StaticClass(), GetActorTransform(), P))
	{
		HolsteredSaber = Saber; Saber->HolsterToBelt(this);
	}
}
void ADukeJediPlayer::SetupPlayerInputComponent(UInputComponent* PlayerInputComponent)
{
	Super::SetupPlayerInputComponent(PlayerInputComponent);
	if (UEnhancedInputComponent* EIC = Cast<UEnhancedInputComponent>(PlayerInputComponent))
	{
		if (StrikeAction) EIC->BindAction(StrikeAction, ETriggerEvent::Triggered, this, &ADukeJediPlayer::OnStrike);
		if (InteractAction) EIC->BindAction(InteractAction, ETriggerEvent::Triggered, this, &ADukeJediPlayer::OnInteract);
		if (HolsterAction) EIC->BindAction(HolsterAction, ETriggerEvent::Triggered, this, &ADukeJediPlayer::OnHolster);
	}
}
void ADukeJediPlayer::OnStrike()
{
	if (!CurrentEquippedWeapon) return;
	if (CurrentEquippedWeapon->WeaponType == EDukeWeaponType::Lightsaber)
	{
		if (SaberComboMontages.Num()) { PlayAnimMontage(SaberComboMontages[ComboIndex % SaberComboMontages.Num()]); ++ComboIndex; }
	}
	else if (ADukeBlasterRifleWeapon* B = Cast<ADukeBlasterRifleWeapon>(CurrentEquippedWeapon)) B->FireBlaster(this);
}
void ADukeJediPlayer::OnInteract()
{
	TArray<AActor*> Near; GetOverlappingActors(Near, ADukeWeaponBase::StaticClass());
	ADukeWeaponBase* Found = nullptr;
	for (AActor* A : Near) if (ADukeWeaponBase* W = Cast<ADukeWeaponBase>(A)) if (W->GetOwner() != this) { Found = W; break; }
	if (!Found) return;
	if (CurrentEquippedWeapon && CurrentEquippedWeapon != HolsteredSaber) CurrentEquippedWeapon->DropWeapon();
	else if (CurrentEquippedWeapon == HolsteredSaber && HolsteredSaber) { HolsteredSaber->bIsBladeActive = false; HolsteredSaber->HolsterToBelt(this); }
	CurrentEquippedWeapon = Found; Found->SetOwner(this); Found->EquipToHand(this);
	if (ADukeLightsaberWeapon* S = Cast<ADukeLightsaberWeapon>(Found)) S->bIsBladeActive = true;
}
void ADukeJediPlayer::OnHolster()
{
	if (!CurrentEquippedWeapon)
	{
		if (HolsteredSaber) { CurrentEquippedWeapon = HolsteredSaber; HolsteredSaber->EquipToHand(this); HolsteredSaber->bIsBladeActive = true; }
		return;
	}
	if (ADukeLightsaberWeapon* S = Cast<ADukeLightsaberWeapon>(CurrentEquippedWeapon)) { S->bIsBladeActive = false; S->HolsterToBelt(this); }
	else CurrentEquippedWeapon->DropWeapon();   // a battlefield pickup is dropped
	CurrentEquippedWeapon = nullptr;
}
